function valoreValido(def, v) {
  if (def.scelte) return def.scelte.some(([x]) => x === v);
  if (def.si) return typeof v === 'boolean';
  return typeof v === 'number' && v >= def.min && v <= def.max && (def.passo !== 1 || Number.isInteger(v));
}

