  const strati = [(conf || {}).generale, ((conf || {}).generi || {})[categoria]];
  return Object.fromEntries(IMPOSTAZIONI.map((d) => {
    let v = d.def;
    for (const s of strati) if (s && valoreValido(d, s[d.chiave])) v = s[d.chiave];
    return [d.chiave, v];
  }));
}

