  // Gli errori vengono anche registrati a parte: il bot Telegram avvisa quando si ripetono
  if (/fallit|errore|non riuscit|non valid|rifiutat|non raggiungibile|non attivo|scartat/i.test(msg)) {
    const key = msg.replace(/[0-9a-f]{12,}|\d+(\.\d+)?/gi, '#').slice(0, 160);
    fs.appendFileSync(CFG.errorsFile, JSON.stringify({ ts, key }) + '\n');
  }
}

function readJsonSafe(file, fallback) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    return fallback;
  }
}

function loadState() {
  let s = readJsonSafe(CFG.stateFile, null);
  if (!s && fs.existsSync(CFG.stateFile)) {
    // illeggibile: se ne tiene una copia invece di sovrascriverlo con uno stato vuoto
    fs.copyFileSync(CFG.stateFile, `${CFG.stateFile}.${Date.now()}.corrotto`);
    log('errore: state.json non leggibile, copia messa da parte e stato ricreato');
  }
  s = s || {};
  return { cursor: 0, queue: [], job: null, done: 0, failed: [], recent: [], lastReview: 0, ...s };
}

function saveState(s) {
  fs.mkdirSync(path.dirname(CFG.stateFile), { recursive: true });
  scriviAtomico(CFG.stateFile, JSON.stringify(s, null, 2));
}

// Lock contro esecuzioni sovrapposte: un file con token. Scade dopo maxMs, cosi' un crash non blocca per sempre.
const LOCK_MAX_MS = 15 * 60 * 1000;
function lockFile(nome) {
  return path.join(CFG.dir, 'state', nome + '.lock');
}
function acquireLock(nome, maxMs = LOCK_MAX_MS) {
  const file = lockFile(nome);
  const token = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
  for (let giro = 0; giro < 2; giro++) {
    try {
      fs.writeFileSync(file, JSON.stringify({ token, creato: new Date().toISOString() }), { flag: 'wx' });
      return token;
    } catch (e) {
      if (e.code !== 'EEXIST') throw e;
      let eta;
      try { eta = Date.now() - fs.statSync(file).mtimeMs; } catch (e2) { continue; } // rilasciato nel frattempo: riprova
      if (eta < maxMs) return null; // occupato da un'altra esecuzione
      try { fs.unlinkSync(file); } catch (e3) { /* gia' rimosso */ }
    }
  }
  return null;
}
function releaseLock(nome, token) {
  const file = lockFile(nome);
  if (token && readJsonSafe(file, {}).token === token) fs.unlinkSync(file);
}
function lockOccupato(nome, maxMs = LOCK_MAX_MS) {
  try { return Date.now() - fs.statSync(lockFile(nome)).mtimeMs < maxMs; } catch (e) { return false; }
}

function readGuidance() {
  return readJsonSafe(CFG.guidanceFile, DEFAULT_GUIDANCE);
}
// Nuove linee guida: la versione precedente va nello storico, poi scrittura atomica
function scriviGuida(prossima, precedente) {
  fs.mkdirSync(CFG.historyDir, { recursive: true });
  fs.writeFileSync(path.join(CFG.historyDir, `guidance-v${precedente.versione}.json`), JSON.stringify(precedente, null, 2));
  scriviAtomico(CFG.guidanceFile, JSON.stringify(prossima, null, 2));
}

// Richiesta HTTP con modulo 'http' (la sandbox di n8n non ha fetch/URL).
// Ritorna {status, ok, headers, buf} senza lanciare su 4xx/5xx.
function req(method, url, { body, ms = 20000 } = {}) {
  return new Promise((resolve, reject) => {
    const m = /^http:\/\/([^:\/]+):(\d+)(\/.*)?$/.exec(url);
    if (!m) return reject(new Error(`URL non valido: ${url}`));
    const data = body ? Buffer.from(JSON.stringify(body)) : null;
    const headers = data ? { 'Content-Type': 'application/json', 'Content-Length': data.length } : {};
    const r = http.request(
      { hostname: m[1], port: Number(m[2]), path: m[3] || '/', method, headers, timeout: ms },
      (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const code = res.statusCode;
          resolve({ status: code, ok: code >= 200 && code < 300, headers: res.headers, buf: Buffer.concat(chunks) });
        });
      }
    );
    r.on('timeout', () => r.destroy(new Error(`timeout ${ms}ms`)));
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

// Chiamate al gateway locale (token non presenti nei blocchi)
function gw(route, body) {
  return new Promise((resolve, reject) => {
    const data = Buffer.from(JSON.stringify(body || {}));
    const r = http.request({ hostname: '127.0.0.1', port: 5790, path: route, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': data.length }, timeout: 900000 }, (res) => {
      const ch = [];
      res.on('data', (c) => ch.push(c));
      res.on('end', () => {
        try { resolve({ status: res.statusCode, ...JSON.parse(Buffer.concat(ch).toString('utf8')) }); } catch (e) { reject(new Error('risposta gateway non valida')); }
      });
    });
    r.on('timeout', () => r.destroy(new Error('timeout gateway')));
    r.on('error', reject);
    r.write(data);
    r.end();
  });
}
// Upload di un brano: il gateway aggiunge l'autenticazione
function gwUpload(nome, buf) {
  return new Promise((resolve, reject) => {
    const r = http.request({ hostname: '127.0.0.1', port: 5790, path: '/ib/upload', method: 'POST', headers: { 'Content-Type': 'application/octet-stream', 'Content-Length': buf.length, 'x-file-name': nome }, timeout: 900000 }, (res) => {
      const ch = [];
      res.on('data', (c) => ch.push(c));
      res.on('end', () => {
        try { resolve({ status: res.statusCode, ...JSON.parse(Buffer.concat(ch).toString('utf8')) }); } catch (e) { reject(new Error('risposta gateway non valida')); }
      });
    });
    r.on('timeout', () => r.destroy(new Error('timeout gateway')));
    r.on('error', reject);
    r.write(buf);
    r.end();
  });
}

async function getJson(url, ms = 20000) {
  const r = await req('GET', url, { ms });
  if (!r.ok) throw Object.assign(new Error(`HTTP ${r.status} ${url}`), { status: r.status });
  return JSON.parse(r.buf.toString('utf8'));
}

async function engineUp() {
  try {
    await getJson(`${CFG.yue}/health`, 5000);
    return true;
  } catch (e) {
    return false;
  }
}

// Il testo passa dal gateway: servizi cloud gratuiti in catena, poi gemma (gateway\testi.js).
// Se il gateway è spento si chiama direttamente il modello locale.
async function llmJson(system, user, maxTokens = 1200) {
  let r;
  try {
    r = await gw('/llm/chat', { system, user, maxTokens });
  } catch (e) {
    if (e.code !== 'ECONNREFUSED') throw e;
    log('gateway spento: chiedo direttamente al modello locale');
    llmJson.ultimo = { servizio: 'locale', modello: CFG.llmModel };
    return llmLocale(system, user, maxTokens);
  }
  if (!r.ok) throw new Error(r.error || `catena dei testi HTTP ${r.status}`);
  if (r.motivi && r.motivi.length) log(`servizi di testo non disponibili (${r.motivi.join('; ')}): ha risposto gemma`);
  else if (r.servizio !== 'locale') log(`testo scritto da ${r.servizio}`);
  llmJson.ultimo = { servizio: r.servizio, modello: r.modello, ms: r.ms }; // chi ha scritto: finisce nella scheda del brano
  return r.dati;
}

// Chiamata diretta al modello locale: ritorna il primo oggetto JSON presente nella risposta.
// gemma ragiona prima di rispondere e il ragionamento consuma max_tokens (visti circa 1500 token):
// al tetto per la risposta si aggiunge questo margine.
const RAGIONAMENTO_TOKEN = 6000;
async function llmLocale(system, user, maxTokens = 1200) {
  const r = await req('POST', `${CFG.llm}/chat/completions`, {
    ms: 600000,
    body: {
      model: CFG.llmModel,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      temperature: 0.8,
      max_tokens: maxTokens + RAGIONAMENTO_TOKEN,
    },
  });
  if (!r.ok) throw new Error(`LLM HTTP ${r.status}`);
  const scelta = JSON.parse(r.buf.toString('utf8')).choices[0];
  if (scelta.finish_reason === 'length') throw new Error('risposta del modello troncata (max_tokens)');
  const text = scelta.message.content || '';
  const a = text.indexOf('{');
  const b = text.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('nessun JSON nella risposta del modello');
  return JSON.parse(text.slice(a, b + 1));
}

function slugify(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'brano';
}

function uniquePath(dir, base, ext) {
  let name = base;
  let i = 2;
  while (fs.existsSync(path.join(dir, name + ext))) name = `${base}-${i++}`;
  return path.join(dir, name + ext);
}

// Cartella di un brano: radice / Yoga o Sottofondo / famiglia / categoria / tipo
function cartellaBrano(categoria, tipo) {
  const c = (CFG.categories || []).find((x) => x.name === categoria) || {};
  const ambito = c.ambito === 'yoga' ? 'Yoga' : 'Sottofondo';
  return path.join(CFG.root, ambito, c.famiglia || 'generale', categoria || 'senza-categoria', tipo || 'senza-tipo');
}

// Slot deterministico: ruota su categoria, tipo e struttura, cosi' i brani sono variati.
function slotFor(cursor, guidance = DEFAULT_GUIDANCE) {
  const n = CFG.categories.length;
  const category = CFG.categories[cursor % n];
  const round = Math.floor(cursor / n);
  const allowed = (guidance.struttura_pref && guidance.struttura_pref[category.name]) || category.strutture;
  const structure = allowed[round % allowed.length];
  const tipo = CFG.tipi[round % CFG.tipi.length];
  return { category: { ...category, bpm: bpmRangeOf(guidance, category) }, tipo, struttura: structure, sezioni: CFG.strutture[structure] };
}

// Intervallo bpm "min-max" da guidance, o il default della categoria
function bpmRangeOf(guidance, category) {
  const m = /^(\d+)\s*-\s*(\d+)$/.exec((guidance.bpm_range || {})[category.name] || '');
  return m ? [Number(m[1]), Number(m[2])] : category.bpm;
}

function clampDur(v) {
  const n = Math.round(Number(v));
  if (!Number.isFinite(n)) return CFG.durDefault;
  return Math.min(CFG.durMax, Math.max(CFG.durMin, n));
}

// Intervallo "min-max" dal suggerimento di durata per categoria (default: intero range).
function durRange(guidance, category) {
  const h = (guidance.durata_hint || {})[category];
  const m = /^(\d+)\s*-\s*(\d+)$/.exec(h || '');
  if (!m) return [CFG.durMin, CFG.durMax];
  return [clampDur(m[1]), clampDur(m[2])];
}

// ---- Richieste al motore: prima il solo score (lo scrive il modello), poi il render dell'audio ----
function richiestaBase(concept, adapters, seed) {
  return {
    style: concept.style,
    lyrics: concept.lyrics,
    cot: (concept.attempts || 0) >= 2 ? 'melody' : 'full', // full: score con melodia e accordi
    ...(adapters.length ? { adapters } : {}),
    seed,
  };
}

// Come nascono gli score (config\score.json, dalla dashboard) e score scelti a mano (state\score.json)
function confScore() { return readJsonSafe(path.join(CFG.dir, 'config', 'score.json'), {}); }
function archivioScore() { return readJsonSafe(path.join(CFG.dir, 'state', 'score.json'), {}); }

// Solo lo score, senza LoRA (agiscono sul render): un secondo di audio e un passo, il resto si butta
function corpoPiano(concept, seed, scrittura) {
  return {
    ...richiestaBase(concept, [], seed),
    duration: 1,
    steps: 1,
    semantic_sampling: { min_tokens: 1, max_tokens: 25 },
    // predefinito 6000 simboli, circa 6 minuti: oltre, il modello sta girando a vuoto
    ...(scrittura || { abc_sampling: { max_tokens: 6000 } }),
    output_format: 'mp3',
  };
}

// Render dell'audio. secondi = durata dello score, se nota: il motore non puo' chiudere prima del 90%.
function corpoRender(concept, adapters, seed, abc, secondi) {
  // 360 s: limite del motore. Si chiede piu' durata dello score, cosi' il brano si chiude da solo
  const durata = Math.min(360, secondi ? Math.ceil(secondi * 1.15) : Math.round(concept.durata_s * 1.2));
  const token = Math.min(9000, Math.round(durata * 25 * 1.2));
  return {
    ...richiestaBase(concept, adapters, seed),
    duration: durata,
    semantic_sampling: { max_tokens: token, ...(secondi ? { min_tokens: Math.floor(secondi * 0.9 * 25) } : {}) },
    ...(abc ? { abc } : { abc_sampling: { max_tokens: Math.max(512, token) } }),
    // WAV per il mastering; dopo un fallimento si chiede l'MP3, che ne puo' fare a meno
    output_format: concept.attempts ? 'mp3' : 'wav32',
  };
}

// Invia una richiesta al motore; ritorna l'id del job, o null se rifiutata
async function inviaSynth(body) {
  const r = await req('POST', `${CFG.yue}/synth`, { body, ms: 20000 });
  inviaSynth.ultimoStato = r.status;
  if (!r.ok) { log(`/synth rifiutato (HTTP ${r.status}): riprovo al prossimo giro`); return null; }
  return JSON.parse(r.buf.toString('utf8')).id;
}

const nuovoSeed = () => Math.floor(Math.random() * 2147483647);

// Rimette in coda il concept del job corrente, o lo scarta dopo maxAttempts tentativi.
function requeue(state, reason) {
  const c = state.job.concept;
  state.job = null;
  c.attempts = (c.attempts || 0) + 1;
  if (c.attempts >= CFG.maxAttempts) {
    state.failed.push({ titolo: c.titolo, categoria: c.categoria, tipo: c.tipo, motivo: reason, at: new Date().toISOString() });
    log(`scartato "${c.titolo}" dopo ${c.attempts} tentativi: ${reason}`);
  } else {
    state.queue.unshift(c);
    log(`riaccodo "${c.titolo}" (tentativo ${c.attempts}): ${reason}`);
  }
}

// Lo score ABC che il motore ha seguito, dalle parti JSON della risposta; null se assente.
function extractAbc(buf, ct) {
  const m = /boundary="?([^";]+)"?/i.exec(ct || '');
  if (!m) return null;
  // si leggono come testo solo le parti JSON: l'audio WAV pesa oltre 100 MB
  const sep = Buffer.from('--' + m[1]);
  for (let da = buf.indexOf(sep); da !== -1;) {
    const a = buf.indexOf(sep, da + sep.length);
    const parte = buf.subarray(da + sep.length, a === -1 ? buf.length : a);
    da = a;
    const i = parte.indexOf('\r\n\r\n');
    if (i === -1 || !/application\/json/i.test(parte.subarray(0, i).toString('utf8'))) continue;
    try {
      const abc = JSON.parse(parte.subarray(i + 4).toString('utf8').trim()).abc;
      if (abc) return abc;
    } catch (e) { /* parte JSON non valida */ }
  }
  return null;
}

// Estrae la traccia audio dalla risposta multipart del motore.
function extractAudio(buf, ct) {
  const m = /boundary="?([^";]+)"?/i.exec(ct || '');
  if (!m) return { data: buf, ext: 'mp3' };
  const sep = Buffer.from('--' + m[1]);
  const parts = [];
  let idx = buf.indexOf(sep);
  while (idx !== -1) {
    const start = idx + sep.length;
    const next = buf.indexOf(sep, start);
    parts.push(buf.subarray(start, next === -1 ? buf.length : next));
    idx = next;
  }
  for (const p of parts) {
    const hEnd = p.indexOf('\r\n\r\n');
    if (hEnd === -1) continue;
    const head = p.subarray(0, hEnd).toString('utf8').toLowerCase();
    if (!(head.includes('audio/') || head.includes('filename'))) continue;
    let data = p.subarray(hEnd + 4);
    if (data.length >= 2 && data[data.length - 2] === 13 && data[data.length - 1] === 10) data = data.subarray(0, -2);
    const ext = /flac/.test(head) ? 'flac' : /wav/.test(head) ? 'wav' : /ogg/.test(head) ? 'ogg' : 'mp3';
    return { data, ext };
  }
  throw new Error('nessuna traccia audio nella risposta');
}

// ---- Apprendimento: ricette, punteggi e scelta del brano successivo (UCB) ----
// Incollato dopo lib.js in ogni blocco. Un voto utente vale CFG.pesoVoto; i dati automatici valgono 1.
// Default, a meno che config\parametri.json (caricato in lib.js) non li sostituisca
CFG.pesoVoto = CFG.pesoVoto ?? 100;
CFG.minVotiAffidabili = CFG.minVotiAffidabili ?? 3;
CFG.maxEsperimenti = CFG.maxEsperimenti ?? 2;
CFG.durataEsperimentoBrani = CFG.durataEsperimentoBrani ?? 10;
CFG.esplorazione = CFG.esplorazione ?? 0.3;

// Tutti i brani della libreria (ogni .json con titolo)
function libraryTracks() {
  const out = [];
  const walk = (dir) => {
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      if (name === '_scartati') continue; // brani scartati dal controllo qualità: non fanno parte della libreria
      if (fs.statSync(full).isDirectory()) walk(full);
      else if (name.endsWith('.json') && name !== 'feedback.json') {
        const meta = readJsonSafe(full, null);
        if (meta && meta.titolo) out.push({ meta, jsonPath: full, audio: name.replace(/\.json$/, '') });
      }
    }
  };
  if (fs.existsSync(CFG.root)) walk(CFG.root);
  return out;
}

// Scrittura atomica di una scheda: chi legge non la trova mai a meta'
function scriviScheda(jsonPath, meta) {
  scriviAtomico(jsonPath, JSON.stringify(meta, null, 2));
}

// Aggiorna solo alcuni campi di una scheda, rileggendola: un voto scritto nel frattempo resta.
// Se la scheda manca o è illeggibile lancia un errore, senza ricrearla con i soli campi.
function aggiornaScheda(jsonPath, campi) {
  const meta = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
  scriviScheda(jsonPath, Object.assign(meta, campi));
}

// Numero progressivo globale dei brani: non si ripete mai e non torna indietro.
// Il contatore vive in state/contatore.json e si incrementa a ogni brano salvato.
CFG.contatoreFile = path.join(CFG.dir, 'state', 'contatore.json');
function numeroProgressivo() {
  let numero = readJsonSafe(CFG.contatoreFile, {}).prossimo;
  // contatore perso o illeggibile: si riparte dal numero più alto in libreria, mai da 1
  if (!Number.isInteger(numero)) numero = libraryTracks().reduce((m, t) => Math.max(m, t.meta.numero_traccia || 0), 0) + 1;
  scriviAtomico(CFG.contatoreFile, JSON.stringify({ prossimo: numero + 1, aggiornato: new Date().toISOString() }, null, 2));
  return numero;
}

// Chiave di ricetta: categoria | struttura | fascia di bpm (b0, b1, b2). Solo ciò che arriva al motore.
function recipeKey(categoria, struttura, band) {
  return `${categoria}|${struttura}|b${band}`;
}

// Il tipo serve a cartella e tag: segue l'energia del genere, non si impara
function tipoDi(energia) {
  const t = ['ambient-pad', 'melodico-dolce', 'ritmico-leggero', 'ritmico-energico', 'ritmico-energico'][(energia || 3) - 1];
  return !CFG.tipi || CFG.tipi.includes(t) ? t : CFG.tipi[0];
}

// Sotto-intervallo bpm della fascia band (0 bassa, 1 media, 2 alta) dentro il range della categoria
function bandRange(range, band) {
  const [lo, hi] = range;
  const step = (hi - lo) / 3;
  return [Math.round(lo + step * band), Math.round(lo + step * (band + 1))];
}

// Voto utente di un brano: unica fonte è il campo voto del suo json
function votoUtente(track) {
  const v = track.meta.voto;
  return v >= 1 && v <= 5 ? v : null;
}

// Segnale di iBroadcast ({voto, fonte} o null): conta solo quando cambia, così vince l'ultimo voto dato.
// Ritorna true se meta.voto è cambiato.
function applicaSegnale(meta, segnale, oraIso) {
  const nuovo = segnale?.voto ?? null;
  if (nuovo === (meta.voto_ib ?? null)) return false;
  meta.voto_ib = nuovo;
  if (nuovo === null || nuovo === meta.voto) return false;
  meta.voto = nuovo;
  meta.voto_fonte = segnale.fonte;
  meta.voto_il = oraIso;
  return true;
}

// Spazio gratuito di iBroadcast (5 GB): oltre la soglia si libera fino all'obiettivo
CFG.spazioIb = { soglia: 4.7e9, obiettivo: 4.5e9 };

// Id da eliminare da iBroadcast. Prima tutto il cestino (occupa spazio); poi i brani del sistema: voto 1, voto 2,
// senza voto o 3, voto 4, a parità i più vecchi. I voti 5 e i brani caricati a mano non si toccano.
function daRimuovere(tracce, nostri, soglia, obiettivo) {
  const peso = (id) => Number(tracce[id].size) || 0;
  const ids = Object.keys(tracce).filter((id) => id !== 'map');
  let usato = ids.reduce((s, id) => s + peso(id), 0);
  if (usato < soglia) return [];
  const via = ids.filter((id) => tracce[id].trashed);
  usato -= via.reduce((s, id) => s + peso(id), 0);
  const classe = (v) => ({ 1: 0, 2: 1, 4: 3 })[v] ?? 2;
  const candidati = nostri.filter((b) => tracce[b.id] && !tracce[b.id].trashed && b.meta.voto !== 5)
    .sort((a, b) => classe(a.meta.voto) - classe(b.meta.voto) || String(a.meta.generato_il || '').localeCompare(String(b.meta.generato_il || '')));
  for (const b of candidati) {
    if (usato <= obiettivo) break;
    via.push(b.id);
    usato -= peso(b.id);
  }
  return via;
}

// Impronta dei voti ("quanti|data dell'ultimo"): cambia anche correggendo un voto già dato
function firmaVoti(tracks) {
  const votati = tracks.filter((t) => votoUtente(t));
  const ultimo = votati.map((t) => t.meta.voto_il || '').sort().pop() || '';
  return `${votati.length}|${ultimo}`;
}

// Statistiche per ricetta: voti utente (peso CFG.pesoVoto) e dati automatici (peso 1)
function recipeStats(tracks) {
  const stats = {};
  for (const t of tracks) {
    if (!t.meta.ricetta) continue;
    // le chiavi vecchie avevano anche il tipo: categoria|tipo|struttura|fascia
    const parti = t.meta.ricetta.split('|');
    const k = parti.length === 4 ? recipeKey(parti[0], parti[2], parti[3].slice(1)) : t.meta.ricetta;
    const s = (stats[k] = stats[k] || { nu: 0, u: 0, na: 0, a: 0 });
    s.na++;
    if (t.meta.qualita && t.meta.qualita.esito === 'ok') s.a++;
    const v = votoUtente(t);
    if (v) { s.nu++; s.u += (v - 1) / 4; } // voto 1..5 -> 0..1
  }
  return stats;
}

// Punteggio di una ricetta: media pesata con prior 0.5; UCB aggiunge esplorazione
function ricettaScore(s, totale) {
  const peso = CFG.pesoVoto;
  const numeratore = 0.5 + peso * (s ? s.u : 0) + (s ? s.a : 0);
  const denominatore = 1 + peso * (s ? s.nu : 0) + (s ? s.na : 0);
  const p = numeratore / denominatore;
  const n = (s ? s.nu * peso + s.na : 0);
  const bonus = CFG.esplorazione * Math.sqrt(Math.log(totale + 2) / (n + 1));
  return { p, score: p + bonus, affidabile: (s ? s.nu : 0) >= CFG.minVotiAffidabili };
}

// Sceglie categoria, tipo, struttura e fascia di bpm per il prossimo brano.
// Ricette non ancora affidabili entrano solo come esperimento, al massimo CFG.maxEsperimenti alla volta.
function pickSlot(state, guidance) {
  const tracks = libraryTracks();
  const stats = recipeStats(tracks);
  const totale = tracks.length;

  // Gli esperimenti terminano quando la ricetta diventa affidabile o dopo N brani
  state.experiments = (state.experiments || []).filter((e) => {
    const s = stats[e.key];
    const affidabile = s && s.nu >= CFG.minVotiAffidabili;
    return !affidabile && totale - e.da < CFG.durataEsperimentoBrani;
  });
  const inEsperimento = new Set(state.experiments.map((e) => e.key));
  const candidati = [];
  for (const cat of CFG.categories) {
    const strutture = (guidance.struttura_pref && guidance.struttura_pref[cat.name]) || cat.strutture;
    const range = durRangeBpm(guidance, cat);
    for (const struttura of strutture) {
      for (let band = 0; band < 3; band++) {
        const key = recipeKey(cat.name, struttura, band);
        const r = ricettaScore(stats[key], totale);
        candidati.push({ key, cat, tipo: tipoDi(cat.energia), struttura, band, range, ...r });
      }
    }
  }
  // Varieta': le categorie degli ultimi due brani non tornano subito, se esistono alternative
  const ultime = (state.recent || []).slice(-5).map((r) => r.categoria);
  const altre = candidati.filter((c) => !ultime.includes(c.cat.name));
  let pool = altre.length ? altre : candidati;
  if (CFG.comandi && CFG.comandi.produciGenere) pool = candidati; // "produci ora" ignora la varieta' recente
  // Rotazione tra i generi: prima si sceglie il genere, con peso più alto per quelli meno rappresentati
  // in libreria (i generi senza brani pesano di più). Poi si applica la logica di ricetta solo a quel genere.
  const conta = {};
  for (const t of tracks) conta[t.meta.categoria] = (conta[t.meta.categoria] || 0) + 1;
  // Peso e stato (attivo/sospeso) per genere da config\parametri.json; "produci ora" forza un genere
  const ov = (n) => CFG.generiOverride[n] || { peso: 1, attivo: true };
  const tutti = [...new Set(pool.map((c) => c.cat.name))];
  let nomi = tutti.filter((n) => ov(n).attivo);
  if (CFG.comandi && CFG.comandi.produciGenere && tutti.includes(CFG.comandi.produciGenere)) nomi = [CFG.comandi.produciGenere];
  else {
    // uno score scelto a mano per un brano nuovo porta avanti il suo genere
    const archivio = readJsonSafe(path.join(CFG.dir, 'state', 'score.json'), {});
    const attesa = (archivio.richieste || []).find((r) => !r.titolo && !(state.scoreUsati || {})[r.id] && CFG.categories.some((c) => c.name === r.categoria));
    if (attesa) { nomi = [attesa.categoria]; pool = candidati; }
  }
  if (!nomi.length) nomi = tutti; // tutti sospesi: la produzione non si ferma
  const pesi = nomi.map((n) => ov(n).peso / Math.pow(1 + (conta[n] || 0), 2));
  let r = Math.random() * pesi.reduce((a, b) => a + b, 0);
  let sceltaCat = nomi[nomi.length - 1];
  for (let i = 0; i < nomi.length; i++) { r -= pesi[i]; if (r <= 0) { sceltaCat = nomi[i]; break; } }
  pool = pool.filter((c) => c.cat.name === sceltaCat);
  candidati.splice(0, candidati.length, ...pool);

  // Prima le ricette affidabili con punteggio migliore; le non affidabili solo se c'è posto negli esperimenti
  const affidabili = candidati.filter((c) => c.affidabile).sort((a, b) => b.score - a.score);
  const nuove = candidati.filter((c) => !c.affidabile).sort((a, b) => b.score - a.score);
  let scelto = null;
  const postoEsperimento = state.experiments.length < CFG.maxEsperimenti;
  if (nuove.length && (postoEsperimento || inEsperimento.has(nuove[0].key)) && Math.random() < 0.5) {
    scelto = nuove.find((c) => inEsperimento.has(c.key)) || nuove[0];
  }
  if (!scelto) scelto = affidabili[0] || nuove[0];
  if (!scelto.affidabile && !inEsperimento.has(scelto.key)) state.experiments.push({ key: scelto.key, da: totale });

  const cat = { ...scelto.cat, bpm: bandRange(scelto.range, scelto.band) };
  return {
    category: cat,
    tipo: scelto.tipo,
    struttura: scelto.struttura,
    sezioni: CFG.strutture[scelto.struttura],
    band: scelto.band,
    ricetta: scelto.key,
    esperimento: !scelto.affidabile,
    punteggio: Number(scelto.score.toFixed(3)),
  };
}

// Intervallo bpm della categoria, da guidance (come in lib.js ma usabile qui)
function durRangeBpm(guidance, cat) {
  const m = /^(\d+)\s*-\s*(\d+)$/.exec((guidance.bpm_range || {})[cat.name] || '');
  return m ? [Number(m[1]), Number(m[2])] : cat.bpm;
}

// ---- Identita' dei generi: stile composto in codice, varianti scelte con UCB sui voti ----

// Statistiche per variante di un genere (voti utente e dati automatici)
function varianteStats(tracks, nomeCategoria) {
  const stats = {};
  for (const t of tracks) {
    if (t.meta.categoria !== nomeCategoria || !t.meta.variante) continue;
    const s = (stats[t.meta.variante] = stats[t.meta.variante] || { nu: 0, u: 0, na: 0, a: 0 });
    s.na++;
    if (t.meta.qualita && t.meta.qualita.esito === 'ok') s.a++;
    const v = votoUtente(t);
    if (v) { s.nu++; s.u += (v - 1) / 4; }
  }
  return stats;
}

// Sceglie la variante del genere con il punteggio migliore (UCB), con un po' di esplorazione
function pickVariante(cat, tracks) {
  const varianti = cat.varianti || [];
  if (!varianti.length) return null;
  const stats = varianteStats(tracks, cat.name);
  const totale = tracks.filter((t) => t.meta.categoria === cat.name).length;
  const scelte = varianti.map((v) => ({ v, ...ricettaScore(stats[v.nome], totale) }));
  scelte.sort((a, b) => b.score - a.score);
  return scelte[0].v;
}

// ---- Memoria di composizione per genere (state\memoria-composizione.json) ----
// Per ogni genere: identita' degli score, strumenti fissi e parametri dei brani già composti.
CFG.memoriaFile = path.join(CFG.dir, 'state', 'memoria-composizione.json');
function leggiMemoria() {
  if (!fs.existsSync(CFG.memoriaFile)) return { generi: {} };
  try {
    const m = JSON.parse(fs.readFileSync(CFG.memoriaFile, 'utf8'));
    if (m && m.generi) return m;
  } catch (e) { /* gestito sotto */ }
  // illeggibile: si mette da parte invece di sovrascriverla
  fs.renameSync(CFG.memoriaFile, `${CFG.memoriaFile}.${Date.now()}.corrotta`);
  log('memoria di composizione non valida: messa da parte, si riparte da vuota');
  return { generi: {} };
}
function salvaMemoria(m) {
  scriviAtomico(CFG.memoriaFile, JSON.stringify(m));
}
const gruppoMemoria = (m, nome) => (m.generi[nome] ||= { brani: [] });

// Voti dei brani composti da noi, per seed dello score
function votiPerSeed(nomeCategoria) {
  const out = {};
  for (const t of libraryTracks()) {
    if (t.meta.categoria === nomeCategoria && t.meta.score && votoUtente(t)) out[t.meta.score.seed] = votoUtente(t);
  }
  return out;
}

// Con l'organico del catalogo: i fissi sempre (il primo guida) piu' uno a scelta, mai lo stesso di seguito.
// Senza (generi creati da Telegram): due fissi scelti una volta e 1 o 2 che cambiano.
function strumentiDelGruppo(cat, g) {
  if (cat.organico) {
    const { fissi, scelta = [] } = cat.organico;
    const nuove = scelta.filter((x) => x !== g.ultimiExtra);
    const extra = (nuove.length ? nuove : scelta)[Math.floor(Math.random() * (nuove.length || scelta.length))];
    g.nucleo = [...fissi];
    g.ultimiExtra = extra || '';
    return extra ? [...fissi, extra] : [...fissi];
  }
  const tutti = [...new Set(cat.strumenti || [])];
  const caso = (v) => v.splice(Math.floor(Math.random() * v.length), 1)[0];
  if (!g.nucleo || !g.nucleo.every((x) => tutti.includes(x))) {
    const scorta = [...tutti];
    g.nucleo = [];
    while (g.nucleo.length < 2 && scorta.length) g.nucleo.push(caso(scorta));
  }
  const resto = tutti.filter((x) => !g.nucleo.includes(x));
  const combinazioni = resto.flatMap((a, i) => [[a], ...resto.slice(i + 1).map((b) => [a, b])]);
  const nuove = combinazioni.filter((c) => c.join() !== g.ultimiExtra);
  const extra = nuove.length ? caso(nuove) : combinazioni[0] || [];
  g.ultimiExtra = extra.join();
  return [...g.nucleo, ...extra];
}

// Un'influenza pesata tra quelle del genere (può essere anche il genere stesso)
function scegliInfluenza(cat) {
  const lista = cat.influenze || [];
  if (!lista.length) return null;
  const tot = lista.reduce((a, b) => a + b.peso, 0);
  let r = Math.random() * tot;
  for (const i of lista) { r -= i.peso; if (r <= 0) return i.genere; }
  return lista[0].genere;
}

// "Si bemolle minore" -> "Bb minor"; vuoto se non riconosciuta
function tonalitaInglese(nome) {
  const m = /^(do|re|mi|fa|sol|la|si)( bemolle| diesis)? (maggiore|minore)$/.exec(String(nome || '').trim().toLowerCase());
  if (!m) return '';
  const nota = { do: 'C', re: 'D', mi: 'E', fa: 'F', sol: 'G', la: 'A', si: 'B' }[m[1]];
  const alterazione = m[2] === ' bemolle' ? 'b' : m[2] === ' diesis' ? '#' : '';
  return `${nota}${alterazione} ${m[3] === 'minore' ? 'minor' : 'major'}`;
}

// ---- Blocchi di stile (usati anche dal gateway per la pagina Linee guida: funzioni senza effetti) ----
// Perche' un termine non può essere un blocco di stile; stringa vuota se va bene
function erroreBlocco(testo, { strumentale = false } = {}) {
  const t = String(testo ?? '').trim();
  if (t.length < 2 || t.length > 60) return 'tra 2 e 60 caratteri';
  if (/[,<>]/.test(t)) return 'senza virgole, < o >';
  if (/^no\s/i.test(t)) return 'niente negazioni: escludi il termine';
  if (/\bbpm\b/i.test(t) || /\b[a-g](#|b)?\s+(major|minor)\b/i.test(t)) return 'bpm e tonalità li mette il sistema';
  if (/^(instrumental|wordless vocals)$/i.test(t)) return 'è un blocco fisso';
  // "singing bowls" è uno strumento
  if (strumentale && /\b(vocals?|vocalist|vocalise|voice|choir|singer|female|male|child|soprano|lyrics|rap|rapping)\b|\bsinging\b(?!\s+bowl)/i.test(t)) return 'le voci non vanno in un genere strumentale';
  return '';
}

// Stile per YuE2 a blocchi: soli descrittori inglesi, nell'ordine tipo, genere, strumenti, ritmo, atmosfera,
// aggiunte, mix, bpm, tonalità. I descrittori di ogni genere sono nel campo "en" del catalogo.
// Il motore non ha un prompt negativo: un blocco escluso viene semplicemente tolto.
function blocchiStile(cat, variante, strumenti, influenza, guidance, { bpm, tonalita, direttive } = {}) {
  const note = direttive || (((typeof CFG !== 'undefined' && CFG.generiOverride) || {})[cat.name] || {}).direttive || [];
  const en = cat.en || { genre: cat.stile };
  // le varianti segnaposto ripetono per intero la descrizione del genere: si saltano
  // con un organico definito le varianti non si aggiungono: nominano altri strumenti e confondono il mix
  const colore = variante && !cat.organico && !(cat.en && variante.keywords === cat.stile) ? variante.keywords : '';
  const mio = (guidance.blocchi_generi || {})[cat.name] || {};
  const esclusi = new Set([...(guidance.style_avoid || []), ...(mio.esclusi || [])].map((s) => String(s).trim().toLowerCase()));
  // [origine, termini, argomento]: l'argomento serve solo alla pagina Linee guida
  const gruppi = [
    ['fisso', cat.vocale_senza_parole ? 'Wordless vocals' : 'Instrumental', 'fisso'],
    ['catalogo', en.genre, 'genere'],
    ...strumenti.map((s) => ['catalogo', (en.instruments || {})[s], 'strumenti']),
    ['catalogo', colore, 'variante'],
    ['catalogo', en.rhythm, 'ritmo'],
    ['catalogo', en.mood, 'atmosfera'],
    ...[].concat(influenza || []).map((i) => ['catalogo', (en.influences || {})[i], 'genere']),
    ['nota', note.map((d) => d.replace(/\.$/, '')).join(', '), 'aggiunte'],
    ['generale', (guidance.style_extra || []).join(', '), 'aggiunte'],
    ['tuo', (mio.aggiunti || []).join(', '), 'aggiunte'],
    ['revisione', ((guidance.stile_generi || {})[cat.name] || []).join(', '), 'aggiunte'],
    ['catalogo', en.space, 'produzione'],
    ['fisso', bpm ? `${bpm} BPM` : '', 'fisso'],
    ['fisso', tonalitaInglese(tonalita), 'fisso'],
    ['fisso', cat.vocale_senza_parole ? 'no lyrics' : 'no vocals', 'fisso'],
  ];
  // il motore pesa le parole: ogni frase compare una volta sola
  const viste = new Set();
  const blocchi = [];
  for (const [origine, valore, argomento] of gruppi) {
    for (const testo of String(valore || '').split(',').map((s) => s.trim()).filter(Boolean)) {
      const chiave = testo.toLowerCase();
      if (viste.has(chiave)) continue;
      viste.add(chiave);
      blocchi.push({ testo, origine, argomento, escluso: origine !== 'fisso' && esclusi.has(chiave) });
    }
  }
  return blocchi;
}

function componiStile(...argomenti) {
  return blocchiStile(...argomenti).filter((b) => !b.escluso).map((b) => b.testo).join(', ');
}

// Divieti del genere, quelli generali e quelli scelti per il genere (solo nella scheda del brano)
function divietiDi(cat, guidance) {
  const mio = (guidance.blocchi_generi || {})[cat.name] || {};
  return [...(cat.vietati || []), ...(guidance.style_avoid || []), ...(mio.esclusi || [])].join(', ');
}

// ---- Messaggi Telegram: impostazioni, fascia oraria e testi. Solo funzioni pure. ----
// Usato dai blocchi n8n (incollato da build-workflow.mjs) e dal gateway (gateway\controllo.js).

const MESSAGGI_FREQUENZE = [30, 60, 120, 180, 240, 360, 720]; // minuti
const TOLLERANZA_STOP_MIN = 15; // l'invio dello stop puo' partire con qualche minuto di ritardo

const MESSAGGI_DEF = {
  riepilogo: {
    etichetta: 'Riepilogo brani',
    descrizione: 'I brani caricati su iBroadcast dall\'ultimo invio, con la frequenza scelta qui sopra.',
    dati: {
      conteggio: 'Numero di brani', titoli: 'Titoli', genere: 'Genere', tipo: 'Tipo e struttura',
      musica: 'Energia, bpm, tonalità', durata: 'Durata', render: 'Tempo di render', id: 'Id iBroadcast', totale: 'Totale prodotti',
    },
  },
  rapporto: {
    etichetta: 'Rapporto giornaliero',
    descrizione: 'Una volta al giorno, alla prima ora della fascia.',
    dati: {
      conteggi: 'Brani, voti, errori', esperimenti: 'Esperimenti attivi', salute: 'Salute del sistema', errori: 'Errori principali',
      migliori: 'Ricette migliori', rivedere: 'Ricette da rivedere', commento: 'Commento automatico',
    },
  },
  avvisi: {
    etichetta: 'Avvisi gravi',
    descrizione: 'Errori ripetuti che richiedono un tuo intervento. Fuori fascia vengono conservati e inviati alla riapertura.',
    dati: { testo: 'Testo dell\'errore', ripetizioni: 'Numero di ripetizioni', ora: 'Ora dell\'ultimo' },
  },
};

function orariValidi(inizio, fine) {
  return Number.isInteger(inizio) && Number.isInteger(fine) && inizio >= 0 && fine <= 24 && inizio < fine;
}

// Impostazioni salvate -> impostazioni complete: cio' che manca o non e' valido torna al predefinito
function impostazioniMessaggi(salvate) {
  const s = salvate || {};
  const orari = orariValidi(s.inizio, s.fine) ? s : { inizio: 8, fine: 22 };
  const tipi = {};
  for (const [nome, def] of Object.entries(MESSAGGI_DEF)) {
    const t = (s.tipi || {})[nome] || {};
    const tutti = Object.keys(def.dati);
    tipi[nome] = { attivo: t.attivo !== false, dati: Array.isArray(t.dati) ? tutti.filter((d) => t.dati.includes(d)) : tutti };
  }
  return {
    frequenzaMin: MESSAGGI_FREQUENZE.includes(s.frequenzaMin) ? s.frequenzaMin : 60,
    inizio: orari.inizio, fine: orari.fine, tipi,
  };
}

const minutiDelGiorno = (d) => d.getHours() * 60 + d.getMinutes();

function inFascia(imp, adesso) {
  const m = minutiDelGiorno(adesso);
  return m >= imp.inizio * 60 && m < imp.fine * 60;
}

// Orario (timestamp) dell'ultimo invio previsto, oppure null fuori fascia. Lo stop e' sempre un invio.
function slotRiepilogo(imp, adesso) {
  const m = minutiDelGiorno(adesso);
  const da = imp.inizio * 60, a = imp.fine * 60;
  if (m < da || m > a + TOLLERANZA_STOP_MIN) return null;
  const s = m >= a ? a : da + Math.floor((m - da) / imp.frequenzaMin) * imp.frequenzaMin;
  return new Date(adesso.getFullYear(), adesso.getMonth(), adesso.getDate(), 0, s).getTime();
}

const durataTesto = (s) => (s ? Math.floor(s / 60) + ':' + String(Math.round(s % 60)).padStart(2, '0') : 'n.d.');
const nd = (v) => v || 'n.d.';

function rigaBrano(b, c) {
  return [
    c('titoli') ? b.titolo : null,
    c('genere') ? nd(b.genere || b.categoria) : null,
    c('tipo') ? `${nd(b.tipo)}/${nd(b.struttura)}` : null,
    c('musica') ? `energia ${nd(b.energia)}/5, ${nd(b.bpm)} bpm, ${nd(b.tonalita)}` : null,
    c('durata') ? durataTesto(b.durata_s) : null,
    c('render') ? `render ${nd(b.render_s)} s` : null,
    c('id') ? `id ${nd(b.ibroadcast && b.ibroadcast.track_id)}` : null,
  ].filter(Boolean).join(' · ');
}

// Un solo messaggio: se l'elenco non ci sta, si indica quanti brani sono stati omessi
function testoRiepilogo(brani, dati, totale) {
  const c = (d) => dati.includes(d);
  const testa = c('conteggio') ? `🎵 Riepilogo: ${brani.length} ${brani.length === 1 ? 'nuovo brano' : 'nuovi brani'} su iBroadcast` : '🎵 Riepilogo brani';
  const coda = c('totale') && totale ? `\nBrani prodotti finora: ${totale}` : '';
  const righe = brani.map((b) => rigaBrano(b, c)).filter(Boolean).map((r) => '• ' + r);
  let corpo = '';
  for (let i = 0; i < righe.length; i++) {
    if (testa.length + corpo.length + righe[i].length + coda.length > 3800) { corpo += `\n… e altri ${righe.length - i} brani`; break; }
    corpo += '\n' + righe[i];
  }
  return testa + (corpo ? '\n' + corpo : '') + (coda ? '\n' + coda : '');
}

function testoAvviso(chiave, info, dati) {
  const c = (d) => dati.includes(d);
  const ora = new Date(info.ultimo);
  const hhmm = String(ora.getHours()).padStart(2, '0') + ':' + String(ora.getMinutes()).padStart(2, '0');
  return [
    'Avviso: errore ripetuto' + (c('ripetizioni') ? ` ${info.n} volte in un'ora` : ''),
    c('ora') ? `Ultima volta alle ${hhmm}` : null,
    c('testo') ? chiave : null,
  ].filter(Boolean).join('\n');
}

CFG.messaggi = impostazioniMessaggi(readJsonSafe(path.join(CFG.dir, 'config', 'parametri.json'), {}).messaggi);
// BLOCCO 5b - Titolo e descrizione: chiede al modello di testo titolo, descrizione e durata.
// Il modello non sceglie lo stile: quello viene composto nel blocco 5c.
const inp = $input.first().json;
if (inp.skip) return [{ json: inp }];

const cat = inp.cat;
const [lo, hi] = cat.bpm;
const system = 'Sei un compositore di musica di sottofondo. Rispondi solo con JSON valido.';
// le prime parole dei titoli recenti: senza questo elenco il modello ripete sempre le stesse ("Eco di...")
const usate = [...new Set((inp.state.recent || []).map((r) => String(r.titolo).split(/[\s'’]+/)[0]).filter((p) => p.length > 2))];
const user = `Proponi titolo e descrizione per un brano STRUMENTALE (nessuna voce) di genere "${cat.genere || cat.name}".
Attivita': ${cat.attivita}. Atmosfera del genere: ${cat.stile}.
Variante: ${inp.variante ? inp.variante.nome : 'base'}.
Rispondi SOLO con un oggetto JSON con questi campi:
- "titolo": titolo breve in italiano, originale e diverso dai titoli comuni, coerente con il genere
- "descrizione": una frase in italiano che spiega a quale attivita' serve
- "bpm": intero tra ${lo} e ${hi}
- "durata_s": intero in secondi tra ${inp.dmin} e ${inp.dmax}
Niente nomi di artisti, marchi o citazioni.${usate.length ? `
Non iniziare il titolo con: ${usate.join(', ')}.` : ''}`;

try {
  const c = await llmJson(system, user, 800);
  return [{ json: { ...inp, c, modello_testo: llmJson.ultimo } }];
} catch (e) {
  // Il modello non e' caricato (il watchdog lo carica nel prossimo minuto): non e' un errore da segnalare
  if (/HTTP 400/.test(e.message)) log('in attesa del modello di testo: riprovo al prossimo giro');
  else log(`generazione concept non riuscita: ${e.message}`);
  return [{ json: { ...inp, skip: true, error: e.message } }];
}

